window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"MnD2ANODy_Q","speaker":"Mia Amor Mottley","role":"Prime Minister","country":"Barbados","region":"Latin America & Caribbean","url":"https://www.youtube.com/watch?v=MnD2ANODy_Q","date":"20260924","title":"🇧🇧 Barbados - Prime Minister Addresses United Nations General Assembly 81st Session | #UNGA","seconds":2065,"words":4191,"counts":{"claims":54,"promises":3,"attacks":1},"topics":[{"topic":"UN reform","share":0.2809,"seconds":580},{"topic":"Climate change","share":0.1008,"seconds":208},{"topic":"Artificial intelligence","share":0.0962,"seconds":199},{"topic":"Caribbean finance","share":0.0683,"seconds":141},{"topic":"Global inequality","share":0.0641,"seconds":132},{"topic":"Haiti security","share":0.0633,"seconds":131},{"topic":"Barbados independence","share":0.0392,"seconds":81},{"topic":"Global conflicts","share":0.0351,"seconds":72},{"topic":"UN peacekeeping","share":0.0335,"seconds":69},{"topic":"Guyana-Venezuela dispute","share":0.0329,"seconds":68},{"topic":"Israel-Gaza conflict","share":0.0327,"seconds":68},{"topic":"Caribbean history","share":0.0317,"seconds":66},{"topic":"Caribbean reparations","share":0.031,"seconds":64},{"topic":"Caribbean slavery","share":0.031,"seconds":64},{"topic":"Cuba sanctions","share":0.03,"seconds":62},{"topic":"Racial equality","share":0.0293,"seconds":61}],"timeline":[[0,65,null],[66,140,"Climate change"],[142,212,"UN reform"],[213,278,"Artificial intelligence"],[279,345,"Caribbean history"],[346,411,"UN reform"],[413,478,"UN reform"],[479,544,"UN reform"],[546,617,"UN reform"],[618,691,"Global conflicts"],[692,760,"Israel-Gaza conflict"],[761,830,"UN peacekeeping"],[831,922,"UN reform"],[922,992,"Artificial intelligence"],[993,1057,"Artificial intelligence"],[1059,1129,"Global inequality"],[1130,1198,"Climate change"],[1199,1265,"Climate change"],[1266,1343,"Caribbean finance"],[1345,1409,"Caribbean finance"],[1411,1479,"Haiti security"],[1480,1543,"Haiti security"],[1544,1606,"Cuba sanctions"],[1608,1675,"Guyana-Venezuela dispute"],[1677,1741,"Caribbean slavery"],[1743,1807,"Caribbean reparations"],[1809,1880,"UN reform"],[1882,1942,"Racial equality"],[1947,2028,"Barbados independence"],[2029,2091,"Global inequality"],[2093,2175,"UN reform"]],"stances":{"Climate change":"Mia Amor Mottley states that the climate crisis is accelerating despite clear science and known solutions.","UN reform":"Mia Amor Mottley argues that the UN theme of restoring trust is appropriate because current cooperation is strained and emphasizes the need to shift from financing reconstruction to investing in prevention.","Artificial intelligence":"Mia Amor Mottley argues that AI development must be anchored in a universal framework to prevent existential risks and emphasizes the need to convert knowledge into action.","Caribbean history":"Mia Amor Mottley states that the Caribbean's shared history of migration and conquest provides a global example where difference does not require division.","Global conflicts":"Mia Amor Mottley states that the scale of human tragedy is mounting due to protracted and fragmented conflicts in multiple regions, exacerbated by hunger, debt, and climate change.","Israel-Gaza conflict":"Mia Amor Mottley states that global stability depends on a two-state solution and calls for the UN to deploy mediation teams.","UN peacekeeping":"Mia Amor Mottley argues that peacekeeping forces require faster deployment, technology enhancement, realistic mandates, predictable financing, and true partnership to effectively support ceasefires and bring peace to affected populations.","Global inequality":"Mia Amor Mottley asserts that the need for wealth redistribution is a critical global issue that remains manifest today and supports the creation of an International Panel on Inequality to address it.","Caribbean finance":"Mia Amor Mottley argues that borrowing costs for climate-vulnerable countries are inequitable and asserts that the Bridgetown initiative has successfully launched a compact to expand access to affordable capital.","Haiti security":"Mia Amor Mottley states that security improvements in Haiti are a prerequisite for the success of efforts to return to constitutional government.","Cuba sanctions":"Mia Amor Mottley states that Barbados has annually opposed the embargo and other unilateral coercive measures against Cuba, calling for constructive engagement based on dialogue and international law.","Guyana-Venezuela dispute":"Mia Amor Mottley states that Barbados supports a stable Venezuela and backs Guyana's peaceful resolution of its territorial dispute with Venezuela through the International Court of Justice, while emphasizing the Caribbean must remain a zone of peace.","Caribbean slavery":"Mia Amor Mottley asserts that the trafficking of enslaved Africans is a grave crime against humanity and notes that Barbados enacted the first slave code in 1661.","Caribbean reparations":"Mia Amor Mottley states that Barbados accepts moral responsibility for the legacy of slavery and supports the revised CARICOM 10-point plan for reparatory justice while emphasizing self-repair.","Racial equality":"Mia Amor Mottley quotes a 1963 speech stating that war will persist until racial superiority is abandoned and skin color loses significance.","Barbados independence":"Mia Amor Mottley emphasizes that Barbados values love and kindness globally while highlighting the nation's 60-year history of independence and its guiding principle of being a friend to all without allegiance to any power."},"claims":[{"t":92,"quote":"the climate crisis is accelerating. Even though the science is clear enough for us to act and many of the solutions are already known and despite unprecedented global wealth, millions remain without reliable access to food, water, health or shelter.","topic":"Climate change","kind":"fact"},{"t":182,"quote":"The reality is that we understand that there is regrettably enough for us to be able to invest in prevention rather than waiting to finance reconstruction.","topic":"UN reform","kind":"fact"},{"t":201,"quote":"We understand enough about the climate crisis to reduce the emissions that are warming our planet and take the necessary steps for our populations to adapt.","topic":"UN reform","kind":"fact"},{"t":213,"quote":"We equally now understand enough about the rapid development of AI to know that as we welcome its promise, we must anchor its development in a universal framework that does not imperil our existence as human beings.","topic":"Artificial intelligence","kind":"fact"},{"t":232,"quote":"The failure, my friends, to address these challenges, therefore, is not one simply of knowledge or capacity. It is our repeated failure to convert what we know into what we do.","topic":"Artificial intelligence","kind":"fact"},{"t":317,"quote":"Against all the odds, the Caribbean produced what Laming called a new kind of global family.","topic":"Caribbean history","kind":"fact"},{"t":366,"quote":"We look forward to your stewardship of this assembly and we move to restore trust and indeed to carry reforms from proposals to implementation.","topic":"UN reform","kind":"fact"},{"t":394,"quote":"transformation and development, peacekeeping and humanitarian aid cannot succeed if member states are unwilling to fund it.","topic":"UN reform","kind":"fact"},{"t":466,"quote":"The Security Council still has 15 members, five of them permanent and armed with that veto. Africa with 54 states has no permanent seat.","topic":"UN reform","kind":"fact"},{"t":503,"quote":"despite constituting one quarter of the world states we have no assured representation within the councils","topic":"UN reform","kind":"fact"},{"t":592,"quote":"We've been told that there are more conflicts today than at any time since the United Nations was established.","topic":"UN reform","kind":"fact"},{"t":604,"quote":"The Oslo Peace Institute reported that in 2025, last year, individuals faced battle related deaths.","topic":"UN reform","kind":"fact"},{"t":618,"quote":"That is almost Barbadis' population. I'm told that this makes it the third most violent year in the postcold war era.","topic":"Global conflicts","kind":"number"},{"t":637,"quote":"whether it is in Gaza or the West Bank or Lebanon or Yemen or Sudan or Ukraine or elsewhere, last year we feared that there was a risk of conflicts in the Middle East widening even further and the conflicts continue.","topic":"Global conflicts","kind":"fact"},{"t":704,"quote":"until there is a two-state solution that respects the rights and territories of both the Israelis and Palestinians, we will continue to live on the edge in this","topic":"Israel-Gaza conflict","kind":"fact"},{"t":778,"quote":"These conflicts need to be supported by a quicker and technology enhanced observer force capable of rapid deployment to monitor and support ceasefires and peace agreements to be given the resources.","topic":"UN peacekeeping","kind":"fact"},{"t":824,"quote":"countries of every size and capacity depend on a system in which rules are made collectively and applied consistently and fairly.","topic":"UN peacekeeping","kind":"fact"},{"t":859,"quote":"Barbados is a co-sponsor of the P4M, a group focused on strengthening multilateralism and to beat back the undertakers who are waiting to bury it.","topic":"UN reform","kind":"fact"},{"t":880,"quote":"His voice has been constant, steady, and absolutely right on all of the critical issues facing humanity.","topic":"UN reform","kind":"fact"},{"t":963,"quote":"AI is already transforming how we work, learn and govern.","topic":"Artificial intelligence","kind":"fact"},{"t":971,"quote":"We have found that it has great capacity to detect disease earlier, predict disasters, improve agriculture, and expand access to education and public services.","topic":"Artificial intelligence","kind":"fact"},{"t":980,"quote":"And yet these same extraordinary systems can just as quickly reproduce discrimination, widen surveillance, and spread falsehoods faster than institutions can respond.","topic":"Artificial intelligence","kind":"fact"},{"t":1002,"quote":"Barbados is so honored to host the second in-person meeting of the Independent International Scientific Panel on Artificial Intelligence, which will be held in November of this year.","topic":"Artificial intelligence","kind":"fact"},{"t":1061,"quote":"exactly 65 years ago, that great Caribbean French African intellectual and psychiatrist France Fallon published what has now become a classic, The Wretched of the Earth.","topic":"Global inequality","kind":"fact"},{"t":1082,"quote":"he said the following. What matters today is the issue which blocks the horizon is the need for a redistribution of wealth.","topic":"Global inequality","kind":"fact"},{"t":1177,"quote":"Anyone who experienced this summer in Europe and elsewhere knows that it was the hottest on record.","topic":"Climate change","kind":"fact"},{"t":1185,"quote":"And the Super El Nino has not even yet hit.","topic":"Climate change","kind":"fact"},{"t":1232,"quote":"At the V20 ministerial dialogue in April of this year, the finance ministers agreed that methane reduction must be treated not only as an environmental priority but also an economic, fiscal, and public health opportunity.","topic":"Climate change","kind":"fact"},{"t":1247,"quote":"We must now implement the climate vulnerable countries need to mobilize approximately $490 billion each year by 2030. And yet the current inflows are roughly $90 billion.","topic":"Climate change","kind":"number"},{"t":1284,"quote":"It is almost 1.2 two percentage points higher for climate vulnerable countries than for advanced economies.","topic":"Caribbean finance","kind":"number"},{"t":1293,"quote":"that actually generates an estimated $62 billion more a year in excess interest payments each year.","topic":"Caribbean finance","kind":"number"},{"t":1313,"quote":"In less than one year, Barbados as chair of the climate vulnerable countries, the V20 countries along with the OPEC fund for international development designed and launched the vulnerability to viability compact on four pillars, bringing about 74 countries along with 16 development finance institutions globally to expand access to affordable long-term capital for education projects, health projects, and water infrastructure.","topic":"Caribbean finance","kind":"fact"},{"t":1357,"quote":"It seeks to provide rapid liquidity when climate shocks create balance of payments pressures for countries.","topic":"Caribbean finance","kind":"fact"},{"t":1371,"quote":"you cannot build hospitals and schools and water infrastructure with 10 and 15year money.","topic":"Caribbean finance","kind":"fact"},{"t":1398,"quote":"for almost 5 years the Bridgetown initiative has consistently argued that climate resilience, debt sustainability and access to affordable finance cannot be treated separately.","topic":"Caribbean finance","kind":"fact"},{"t":1452,"quote":"The security crisis continues to retire political renewal and economic recovery.","topic":"Haiti security","kind":"fact"},{"t":1459,"quote":"preparations for a return to constitutional government, yes, are moving forward even with great","topic":"Haiti security","kind":"fact"},{"t":1493,"quote":"it was in 2022 that this recent more heightened state of insecurity began with the fuel riots just before the general assembly met in And In 2026, we have not kept faith with providing the level of security that would minimize the loss of life.","topic":"Haiti security","kind":"fact"},{"t":1561,"quote":"Barbados has each year opposed the use of the embargo and other unilateral coercive measures against Cuba.","topic":"Cuba sanctions","kind":"fact"},{"t":1589,"quote":"Venezuela who regrettably are recovering from the devastating double earthquakes in June.","topic":"Cuba sanctions","kind":"fact"},{"t":1613,"quote":"A stable, sovereign, peaceful, and democratic Venezuela is vital to the security and prosperity of not just Latin America, but the wider Caribbean.","topic":"Guyana-Venezuela dispute","kind":"fact"},{"t":1626,"quote":"I must take this opportunity to reiterate Barbados's steadfast support to its sister of Cariccom, its sister Caraccom country, Guyana, as it seeks to bring a peaceful resolution through the International Court of Justice for the long outstanding territorial controversy with Venezuela.","topic":"Guyana-Venezuela dispute","kind":"fact"},{"t":1680,"quote":"On March 25th of this year, a historic resolution was passed in this general assembly.","topic":"Caribbean slavery","kind":"fact"},{"t":1718,"quote":"it was my country, Barbados, that passed the first slave code that the world knew in 1661 to deal with cattle slavery.","topic":"Caribbean slavery","kind":"self_credit"},{"t":1763,"quote":"As a result, in July of this year, CARACOM heads of government approved the revised CARACOM 10-point plan for reparatory justice for the Caribbean, for Africa, and for those countries concerned.","topic":"Caribbean reparations","kind":"fact"},{"t":1811,"quote":"the mindset that established, justified, and sustained slavery is the same mindset that sustains the iniquities and the inequities within the power structures of this very institution and within the international financial architecture.","topic":"UN reform","kind":"fact"},{"t":1830,"quote":"It is the same It is the same mindset that caused a global map to remain grossly inaccurate on the size of Africa for centuries.","topic":"UN reform","kind":"fact"},{"t":1897,"quote":"Until the philosophy which holds one race superior and another inferior is finally and permanently discredited and abandoned. Everywhere is war.","topic":"Racial equality","kind":"fact"},{"t":1923,"quote":"until they are no longer first class and secondass citizens of any nation. Until the color of a man's skin has of no more significance than the color of his eyes, there will be war.","topic":"Racial equality","kind":"fact"},{"t":1987,"quote":"The 9th of December this year will mark 60 years since Barbados took its place in this organization, emerging into independence after 340 years of imperial subjugation.","topic":"Barbados independence","kind":"number"},{"t":2003,"quote":"On a wintry 9th of December 1966, just nine days after we achieved independence and on the very day of our admission to the United Nations, our first prime minister, the right excellent Errol Barrow, set out what coupled with the principles of this has remained our guiding principle in dealing with the world that Barbados is a friend of all and a satellite of none.","topic":"Barbados independence","kind":"fact"},{"t":2037,"quote":"Fannon had highlighted only five years earlier in the text I quoted.","topic":"Global inequality","kind":"fact"},{"t":2072,"quote":"Much good has been done by this UN in the last 60 and in fact 80 years.","topic":"Global inequality","kind":"number"},{"t":2105,"quote":"Earlier this year, our poet laurate stood at this rostrm and reminded us in this assembly","topic":"UN reform","kind":"fact"}],"promises":[{"t":438,"quote":"Barbados has consistently met that and I give this body the assurance that we will continue to do so.","topic":"UN reform","kind":"promise"},{"t":532,"quote":"Barbados is therefore joining 123 other member states in supporting the Franco Mexican initiative on the use of the veto in the cases of mass atrocities","topic":"UN reform","kind":"promise"},{"t":911,"quote":"Barbados joins its sister member states in the Caribbean community in pledging its full support for the candidature of Ambassador Carolyn Rodriguez Burkett","topic":"UN reform","kind":"promise"}],"attacks":[{"t":404,"quote":"no organizational chart can overcome the refusal of states to respect decisions that they find inconvenient.","topic":"UN reform","target":"Opposing states"}],"greece":[],"said":[],"pickup":[],"transcript":[{"t":0,"topic":null,"text":"The assembly will hear an address by her excellency Mia Amour Mle, Prime Minister, Minister for Economic Affairs and Development and Minister for National Security of Barbados. I request protocol to escort her excellency and invite her to address the assembly. Mr. President, excellencies, my friends, we meet at a time when the obstacles confronting human progress are Obstacles to peace, obstacles to food and clean water, obstacles to finance, medicine and education, obstacles to movement and opportunity, obstacles to technology, to the knowledge and infrastructure needed to use it."},{"t":66,"topic":"Climate change","text":"and increasingly obstacles between nations, between communities, and between people who no longer agree on the same facts or trust the same War continues to destroy lives and communities. Even though the international community possesses more tools than ever, ever before to prevent conflict and to facilitate dialogue, the climate crisis is accelerating. Even though the science is clear enough for us to act and many of the solutions are already known and despite unprecedented global wealth, millions remain without reliable access to food, water, health or shelter. These challenges, my friends, are creating the poly crises of which we constantly speak. And at the same time, new challenges are emerging. Artificial intelligence is opening extraordinary possibilities in health, education, science, and productivity while also creating new risk of exclusion, exploitation, surveillance, and the distortion of truth."},{"t":142,"topic":"UN reform","text":"And yet, the cooperation needed to confront these under strain. It is why I believe the theme this year is so apt. Restoring trust, managing transformation, a united nation that delivers for all. The theme reminds us that we have institutions created to preserve peace, to advance development, and yes, to protect human dignity. The institutions are these very United Nations. We have shared principles grounded in sovereign equality and in the recognition that our responsibilities extend beyond borders. The reality is that we understand that there is regrettably enough for us to be able to invest in prevention rather than waiting to finance reconstruction. We understand enough about the climate crisis to reduce the emissions that are warming our planet and take the necessary steps for our populations to adapt."},{"t":213,"topic":"Artificial intelligence","text":"We equally now understand enough about the rapid development of AI to know that as we welcome its promise, we must anchor its development in a universal framework that does not imperil our existence as human beings. The failure, my friends, to address these challenges, therefore, is not one simply of knowledge or capacity. It is our repeated failure to convert what we know into what we do. To turn principle into practice and global capacity into So beneath our many crises lies yet another one. And yes, it is a crisis of Mr. President, that responsibility begins here in these halls. The transformation we seek for a better world will only happen when we trust each other and we accept our responsibility for each other. We in the Caribbean understand something about the necessity of living together."},{"t":279,"topic":"Caribbean history","text":"We had no Barbadian novelist and essaist George Laming once described the Caribbean as perhaps the first global experiment in human history bringing together and I quote every branch of the human family from the indigenous peoples of the Americas to the diverse peoples from Africa, Europe and Asia. It is as though that we through this torturous and shared history of migration, conquest, slavery, and the difficult work of constructing a common national and regional destiny that we give the world an example to follow. Against all the odds, the Caribbean produced what Laming called a new kind of global family. Our history has taught us that difference need not mean division, that coexistence requires dialogue and and that those without the power to compel must learn the power of These are not merely Caribbean lessons."},{"t":346,"topic":"UN reform","text":"They're universal. And it is in this spirit I'd like to thank her excellency Annalena Burbach for her leadership of the general assembly's 80th session and for helping to advance the work of the member states on UN reform and to you Mr. President. Barbados extends its warm congratulations. We look forward to your stewardship of this assembly and we move to restore trust and indeed to carry reforms from proposals to implementation. But reform cannot be selective. We cannot move swiftly to reorganize offices and reporting lines while allowing the most consequential questions of power and representation to remain unresolved. transformation and development, peacekeeping and humanitarian aid cannot succeed if member states are unwilling to fund it. Let's be very clear, no organizational chart can overcome the refusal of states to respect decisions that they find inconvenient."},{"t":413,"topic":"UN reform","text":"We cannot continue to ask international organizations to do more while failing to provide them with the resources necessary to fulfill the mandates that we ourselves have agreed. And if member states believe in the that they have created, then we must also be prepared to sustain them. Barbados has consistently met that and I give this body the assurance that we will continue to do so. Our commitment to multilateralism, to an international rules-based order must be measured not only by what we ask of these institutions but by our willingness to support them. So yes, let us improve the machinery but let us also reform the exercise of power. The Security Council still has 15 members, five of them permanent and armed with that veto. Africa with 54 states has no permanent seat."},{"t":479,"topic":"UN reform","text":"And you've heard speaker after speaker after speaker come to this platform to say that this must change. Small island developing states equally confront threats that now reach squarely into the council's mandate from climate insecurity and illicit arm flows to organized crime and displacement. And yet despite constituting one quarter of the world states we have no assured representation within the councils. This too my friends must change and the world we know has already changed. The council has not changed with it. But reform is not only about who sits at the table. It is about how power is Barbados is therefore joining 123 other member states in supporting the Franco Mexican initiative on the use of the veto in the cases of mass atrocities."},{"t":546,"topic":"UN reform","text":"Its principle is fundamental. where populations face genocide, crimes against humanity or large-scale war crimes, the veto should not be allowed to paralyze the Security Council when action is most urgently needed. This is why people are losing trust in the United Nations and its council. And Mr. President, it's not fair to the majority of member states who still believe in the promise of this body. Even as we call for greater equity with the reform of the security council, we must equally reform the secretariat to better support peacekeeping and the resolution of conflicts. We've been told that there are more conflicts today than at any time since the United Nations was established. And regrettably, these conflicts are in almost every corner of the planet. The Oslo Peace Institute reported that in 2025, last year, individuals faced battle related deaths."},{"t":618,"topic":"Global conflicts","text":"That is almost Barbadis' population. I'm told that this makes it the third most violent year in the postcold war era. My friends, the scale of human tragedy is mounting. And whether it is in Gaza or the West Bank or Lebanon or Yemen or Sudan or Ukraine or elsewhere, last year we feared that there was a risk of conflicts in the Middle East widening even further and the conflicts continue. These fears regrettably have come to pass and with a global impact. indeed, conflicts are more protracted and more fragmented. And when coupled with hunger and unsustainable debt on a warming planet, it becomes a veritable hell for the citizens of those Increases in energy and transport costs and in interest rates have spurred inflation."},{"t":692,"topic":"Israel-Gaza conflict","text":"It means that no one even on the other side of the world can escape the hardships in meeting their daily needs. The truth is, until there is a two-state solution that respects the rights and territories of both the Israelis and Palestinians, we will continue to live on the edge in this And you may well ask, how have we gotten here? We need to address with laser-like focus each and every one of these Legitimacy demands that of us. And let us let the UN deliberately and systematically deploy nimble mediation teams led by political leaders, current and retired, on behalf of the Secretary General and enjoying the Secretary General's confidence and authority and the respect of member states."},{"t":761,"topic":"UN peacekeeping","text":"This, my friends, will help lift the heavy weight necessary to end these multiple conflicts and to bring peace and dignity to those affected populations. We know that many hands make light work and we can't ignore it. These conflicts need to be supported by a quicker and technology enhanced observer force capable of rapid deployment to monitor and support ceasefires and peace agreements to be given the resources. These peacekeeping forces must be given realistic mandates, predictable financing and true partnership. Let us work, my friends, together with the parties to these conflicts to build dialogue and to bring opportunities for investment and jobs to the affected populations so that they too can live properly. And as for the wider international legal order, we know that countries of every size and capacity depend on a system in which rules are made collectively and applied consistently and fairly."},{"t":831,"topic":"UN reform","text":"But if we don't act early enough, we have trouble. And that is why we say that the UN must receive the resources and the resolve to act before the guns speak and not after the guns start to fly. My friends, without an equitable rules-based order, smaller states like mine will simply cease to exist in this world. And that is why Barbados is a co-sponsor of the P4M, a group focused on strengthening multilateralism and to beat back the undertakers who are waiting to bury it. Mr. President, I would like to express profound appreciation to the Secretary General, my brother Antonio Gutirez. His voice has been constant, steady, and absolutely right on all of the critical issues facing humanity. And to his deputy, Amina Muhammad, we also say thank you for taking the journey without diverting from the principles and the core values of this As the United Nations undertakes the important task of selecting its next secretary general, Barbados joins its sister member states in the Caribbean community in pledging its full support for the candidature of Ambassador Carolyn Rodriguez Burkett"},{"t":922,"topic":"Artificial intelligence","text":"of Guyana at a moment when the international community is being called upon to renew its faith in multilateralism. We believe that Ambassador Rodriguez Burkett brings to this task the experience, the skills and the understanding to serve the entire membership of this organization. Indeed, Mr. President, I believe that others think so too. I'd like sir to turn to the topic of artificial intelligence which is one of our new challenges. AI is already transforming how we work, learn and govern. And it is clear that its potential is extraordinary. We have found that it has great capacity to detect disease earlier, predict disasters, improve agriculture, and expand access to education and public services. And yet these same extraordinary systems can just as quickly reproduce discrimination, widen surveillance, and spread falsehoods faster than institutions can respond."},{"t":993,"topic":"Artificial intelligence","text":"We must not allow a new technological age to reproduce all hierarchies of access and power. And this is why Barbados is so honored to host the second in-person meeting of the Independent International Scientific Panel on Artificial Intelligence, which will be held in November of this year. We recognize that yesterday's Security Council encounter may well and should speeden the question of how we as a global community deals with this issue. In the growing age of AI, governance cannot be left to voluntary corporate practices or to a small number of technologically advanced states. We need globally agreed rules that protect human dignity, preserve meaningful human oversight, and ensure that the benefits of AI are shared widely and equitably. I caution a technology that will affect every state must be governed by the rules that every state has had the opportunity to shape."},{"t":1059,"topic":"Global inequality","text":"Mr. President, exactly 65 years ago, that great Caribbean French African intellectual and psychiatrist France Fallon published what has now become a classic, The Wretched of the Earth. And across the vast range of observations and analysis that he made in that extraordinarily lucid and precient book book, he said the following. What matters today is the issue which blocks the horizon is the need for a redistribution of wealth. Humanity will have to address this question no matter how devastating the consequences may be. My friends, this was haringly true in and sadly remains manifest today. This is why Barbados throws its full support behind the establishment of the International Panel on inequality that is being proposed. Growing inequality is at the center of geopolitical discussions, tensions, distrust in institutions, and indeed the increasing number of conflicts that we see."},{"t":1130,"topic":"Climate change","text":"It is for this reason that we reject the notion that governments must refrain from policy interventions that are essential to creating a level and fair playing field for ordinary citizens. We know that it is the policy choices of government that has led to this injustice and it is the policy choices of governments that must now remove it. For us, this is as important a battle of the cl as the climate crisis. And Mr. President, that brings me to that Minister Murat Kurum representing the incoming COP 31 presidency has put the challenge plainly. The time for simply setting out goals is behind us. Anyone who experienced this summer in Europe and elsewhere knows that it was the hottest on record. And the Super El Nino has not even yet hit. The proposed action agenda places methane reduction at the center of climate implementation and we welcome that focus."},{"t":1199,"topic":"Climate change","text":"It is true that carbon dioxide must remain central to the global energy transition, but emissions are not falling quickly enough and the full benefits of action will take time to emerge. So, Mr. President under Barbados's presidency of the CVF climate vulnerable forum and its V20 74 countries got together and advanced the call to pull the methane emergency break. At the V20 ministerial dialogue in April of this year, the finance ministers agreed that methane reduction must be treated not only as an environmental priority but also an economic, fiscal, and public health opportunity. We must now implement the climate vulnerable countries need to mobilize approximately $490 billion each year by 2030. And yet the current inflows are roughly $90 billion."},{"t":1266,"topic":"Caribbean finance","text":"As the young people in Barbados would say, the math simply ain't math. We must also correct the inequity of the borrowing cost that these countries face. It is almost 1.2 two percentage points higher for climate vulnerable countries than for advanced economies. Now, that figure seems small to you, but that actually generates an estimated $62 billion more a year in excess interest payments each year. This cannot be fair. So that believe me when I say that change is possible as we have seen consistently with measures from the Bridgetown initiative. In less than one year, Barbados as chair of the climate vulnerable countries, the V20 countries along with the OPEC fund for international development designed and launched the vulnerability to viability compact on four pillars, bringing about 74 countries along with 16 development finance institutions globally to expand access to affordable long-term capital for education projects, health projects, and water infrastructure."},{"t":1345,"topic":"Caribbean finance","text":"The CVF also had its governors of the central bank meet to establish the lifeline fund which will shortly be operationalized. It seeks to provide rapid liquidity when climate shocks create balance of payments pressures for countries. So we are moving to help ourselves. We have been resolute and the reason for it is that we know that you cannot build hospitals and schools and water infrastructure with 10 and 15year money. It crowds out critical investments for our people and leaves you flatfooted and that is why this important initiative represents real progress. But mechanisms such as this one cannot on their own address the underlying flaws of the international financial I repeat that for almost 5 years the Bridgetown initiative has consistently argued that climate resilience, debt sustainability and access to affordable finance cannot be treated separately."},{"t":1411,"topic":"Haiti security","text":"For many vulnerable countries, the problem is not simply the availability of capital, but whether we have the fiscal space to borrow and to invest on reasonable terms. Mr. President, as I turn to my region in the Caribbean, I'd like to highlight a series of crises that continue to threaten our peace, stability, and development. Let me say at the outset that when I speak about letting many hands make light work when it comes to conflict resolution that this is one of the areas in which the political leaders of the Caribbean can play a pivotal role in its own region. Firstly, Haiti. The security crisis continues to retire political renewal and economic recovery. And still the preparations for a return to constitutional government, yes, are moving forward even with great But those efforts cannot succeed unless security improves, particularly in the areas containing more than half of Haiti's electorate in the capital and surrounding areas."},{"t":1480,"topic":"Haiti security","text":"Barbados therefore supports the full deployment that has been too too too long promised and the renewal of the mandate of the gang suppression force. Let me remind you that it was in 2022 that this recent more heightened state of insecurity began with the fuel riots just before the general assembly met in And in 2026, we have not kept faith with providing the level of security that would minimize the loss of life. At the same time, we have to give thanks where thanks is due. And there are member states who have contributed in whatever way to helping Haiti find its path. This includes of course the Caribbean community's eminent persons group which has been helping to build consensus and maintain engagement with key international partners in the last few In addition, Mr. President, we are deeply concerned by the worsening humanitarian pressures facing the people of Cuba."},{"t":1544,"topic":"Cuba sanctions","text":"Too many people are suffering. Too many people. Restrictions on trade, finance, and access to fuel are intensifying hardship, not only for Cuban citizens, but for all others who study and live there. Barbados has each year opposed the use of the embargo and other unilateral coercive measures against Cuba. And as always, we call for constructive engagement. constructive engagement grounded in dialogue, sovereign equality, and respect for international law. That is why we are here as individual states. We will also extend our continued solidarity to the people of Venezuela who regrettably are recovering from the devastating double earthquakes in June. The horror was mind-blowing. Barbados was proud to stand with our neighbor in the immediate aftermath, dispatching our field hospital and personnel to Venezuela."},{"t":1608,"topic":"Guyana-Venezuela dispute","text":"We remain committed to supporting them in their longer term recovery. A stable, sovereign, peaceful, and democratic Venezuela is vital to the security and prosperity of not just Latin America, but the wider Caribbean. In this regard, however, I must take this opportunity to reiterate Barbados's steadfast support to its sister of Cariccom, its sister Caraccom country, Guyana, as it seeks to bring a peaceful resolution through the International Court of Justice for the long outstanding territorial controversy with Venezuela. This is in the interests of the people of Guyana, the people of Venezuela, and the wider people of the Caribbean and Latin America. The Caribbean, my friends, must remain a zone of peace. We cannot accept our region becoming a theater. We cannot accept our region becoming a theater for confrontation or for the unilateral and unjustified use of force."},{"t":1677,"topic":"Caribbean slavery","text":"Mr. President, brings me to another matter. On March 25th of this year, a historic resolution was passed in this general assembly. The overwhelming majority of states acknowledged the truth that we in the Caribbean long knew the trafficking of enslaved African and racialized cattle enslavement of is the gravest crime against humanity. and we know it. Regrettably, we still carry the scars. I've reminded us that it was my country, Barbados, that passed the first slave code that the world knew in 1661 to deal with cattle slavery. Others regrettably followed, including the infamous code noir of 1685. That codeir was only repealed this year and then hence the wounds are still raw."},{"t":1743,"topic":"Caribbean reparations","text":"We in Barbados accept the moral responsibility of removing the cross of slavery with its horrific consequences. We must effect healing through reparatory justice for it is the right thing to do. As a result, in July of this year, CARACOM heads of government approved the revised CARACOM 10-point plan for reparatory justice for the Caribbean, for Africa, and for those countries concerned. The honest engagement must begin. And I thank President Mahama of Ghana for coming to the table with the force with which he has come. We do not ask for reparations without accepting responsibility for our own self-repair which we have undertaken for decades. I want to be very clear about this. Mr. Spe, Mr. President, I make the same mistake as President Muhammad. We are parliamentarians. I want to make this clear."},{"t":1809,"topic":"UN reform","text":"Let there be no doubt, Mr. president that the mindset that established, justified, and sustained slavery is the same mindset that sustains the iniquities and the inequities within the power structures of this very institution and within the international financial architecture. It is the same It is the same mindset that caused a global map to remain grossly inaccurate on the size of Africa for centuries. As if the true size of Africa would intimidate the rest of the world into understanding its power. Mr. President, if we want to restore trust in these United Nations and we want to manage transformation as is your theme and we want a UN that truly delivers for everyone, then at its core, we must treat every human being as having equal value and deserving respect."},{"t":1882,"topic":"Racial equality","text":"And I can find no better reference than his majesty Haley Salassie speaking in this very assembly on the 4th of October 1963. And those who know the words can say it with me. Until the philosophy which holds one race superior and another inferior is finally and permanently discredited and abandoned. Everywhere is war. until they are no longer first class and secondass citizens of any nation. Until the color of a man's skin has of no more significance than the color of his eyes, there will be war. But Mr. president equally."},{"t":1947,"topic":"Barbados independence","text":"There will be no trust and no We want peace. And in the words of that iconic song made famous by Dion Warrick, what the world needs now is love. Sweet love. It's the only thing that there's just too little love. No, not just for some, but for everyone, love and a little kindness. So, Mr. President, I end this statement by returning to the beginning of a milestones of profound importance to my country and its relationship to the world. The 9th of December this year will mark 60 years since Barbados took its place in this organization, emerging into independence after 340 years of imperial subjugation. On a wintry 9th of December 1966, just nine days after we achieved independence and on the very day of our admission to the United Nations, our first prime minister, the right excellent Errol Barrow, set out what coupled with the principles of this has remained our guiding principle in dealing with the world that Barbados is a friend of all and a satellite of none."},{"t":2029,"topic":"Global inequality","text":"Indeed, Prime Minister Barrow spoke of a world marked by profound inequalities in wealth and opportunity which Fannon had highlighted only five years earlier in the text I quoted. And drawing from Prime Minister Barrow's language where he quoted from the Hebrew Bible, he warned that newly independent countries could not remain heers of wood and drawers of water while the wealth of the world flowed elsewhere. He saw the United Nations as having to put the eradication of poverty at the center of its role. Do not question, therefore, why we view it as our duty to fight increasing global inequality. Much good has been done by this UN in the last 60 and in fact 80 years. During this time, our membership in the United Nations has been essential to Barbados's expression of its sovereignty and its participation as an equal member of the international community."},{"t":2093,"topic":"UN reform","text":"These halls have given us a place to speak in our own name, to defend the interests of our people and others, and to help shape the decisions that affect us all. Mr. president. Earlier this year, our poet laurate stood at this rostrm and reminded us in this assembly and I quote, \"The very name United Nations implies a commitment to ignite the fires of conscience, empathy, unity, and equity. This UN, this United Nations must continue to stoke those fires for a transformed and inclusive world. I say to you as I leave this rostroom, let us together ensure that the flames of hope, peace, and dignity burn so bright that in the midst of all the odds against us that they shine on all of the world. I thank you. On behalf of the assembly, I wish to thank the Prime Minister, Minister for Economic Affairs and Development and Minister for National Security of of"}],"compare":[{"topic":"UN & its reform","share":0.3144,"mean":0.2042,"rank":40,"others":170},{"topic":"Climate Change","share":0.1008,"mean":0.0425,"rank":28,"others":77},{"topic":"Latin America","share":0.1,"mean":0.0042,"rank":2,"others":12},{"topic":"Artificial Intelligence","share":0.0962,"mean":0.0502,"rank":38,"others":83},{"topic":"Global Economy","share":0.0641,"mean":0.0143,"rank":24,"others":31},{"topic":"Haiti","share":0.0633,"mean":0.0062,"rank":9,"others":11},{"topic":"Reparations","share":0.062,"mean":0.0041,"rank":5,"others":13},{"topic":"International Law & Order","share":0.0351,"mean":0.0605,"rank":102,"others":102}]};
